let x = 10;
let y = x;
y = 20;
console.log(x); // 10 — primitive copy

const list1 = [1, 2, 3];
const list2 = list1;
list2.push(4);
console.log(list1.length); // 4 — same array reference

const clone = [...list1]; // shallow copy — new array, same element refs
clone.push(5);
console.log(list1.length); // 4 — independent array
